import{c as l,Q as n,j as t,m as s}from"./chunks/framework.DOi4mjdC.js";const e="/assets/allreduce-60.BN31VXNs.png",p="/assets/%E9%9D%9E%E5%A4%9A%E8%BD%AE%E5%88%87%E5%88%86%E5%9C%BA%E6%99%AF%E4%B8%8B4%E5%8D%A1AlltoAll%E9%80%9A%E4%BF%A1.CCHyvvIv.png",i="/assets/3%E8%BD%AE%E5%88%87%E5%88%86%E5%9C%BA%E6%99%AF%E4%B8%8B4%E5%8D%A1AlltoAll%E9%80%9A%E4%BF%A1.B2Ke3xtr.png",c="/assets/%E7%AC%AC%E4%B8%80%E8%BD%AE4%E5%8D%A1AlltoAll%E7%A4%BA%E6%84%8F%E5%9B%BE.jd9tWHT7.png",g=JSON.parse('{"title":"AlltoAll","description":"","frontmatter":{},"headers":[{"level":1,"title":"AlltoAll","slug":"alltoall"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/AlltoAll.md","filePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/AlltoAll.md"}'),o={name:"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/AlltoAll.md"};function d(r,a,A,u,h,C){return n(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="alltoall" tabindex="-1">AlltoAll <a class="header-anchor" href="#alltoall" aria-label="Permalink to &quot;AlltoAll&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>集合通信AlltoAll的任务下发接口，返回该任务的标识handleId给用户。AlltoAll的功能为：每张卡向通信域内所有卡发送相同数据量的数据，并从所有卡接收相同数据量的数据。结合原型中的参数，描述接口功能，具体为，第j张卡接收到来自第i张卡的sendBuf中第j块数据，并将该数据存放到本卡recvBuf中第i块的位置。</p><p><img src="'+e+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool commit = false&gt;</span></span>
<span class="line"><span>__aicore__ inline HcclHandle AlltoAll(GM_ADDR sendBuf, GM_ADDR recvBuf, uint64_t dataCount, HcclDataType dataType, uint64_t strideCount = 0, uint8_t repeat = 1)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>commit</td><td>输入</td><td>bool类型。参数取值如下： true：在调用Prepare接口时，Commit同步通知服务端可以执行该通信任务。false：在调用Prepare接口时，不通知服务端执行该通信任务。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>sendBuf</td><td>输入</td><td>源数据buffer地址。</td></tr><tr><td>recvBuf</td><td>输出</td><td>目的数据buffer地址，集合通信结果输出到此buffer中。</td></tr><tr><td>dataCount</td><td>输入</td><td>本卡向通信域内其它每张卡收发的数据量，单位为sizeof(dataType)。 例如，通信域内共4张卡，每张卡的sendBuf中均有4个fp16的数据，那么dataCount=1。</td></tr><tr><td>dataType</td><td>输入</td><td>AlltoAll操作的数据类型，目前支持HcclDataType包含的全部数据类型，HcclDataType详细可参考表1。</td></tr><tr><td>strideCount</td><td>输入</td><td>多轮切分场景下，一次AlltoAll任务中，每张卡内参与通信的数据块间的间隔。默认值为0，表示数据块内存连续。 strideCount=0，每张卡内参与通信的数据块内存连续。卡rank_j收到来自卡rank_i的sendBuf中第j块数据，且数据块间的偏移数据量为j<em>dataCount，并将该数据存放于本卡recvBuf中第i块的位置，且偏移数据量为i</em>dataCount。strideCount&gt;0，每张卡内参与通信的相邻数据块的起始地址偏移数据量为strideCount。卡rank_j收到来自卡rank_i的sendBuf中第j块数据，且数据块间的偏移数据量为j<em>strideCount，并将该数据存放于本卡recvBuf中第i块的位置，且偏移数据量为i</em>strideCount。 注意：上述的偏移数据量为数据个数，单位为sizeof(dataType)。</td></tr><tr><td>repeat</td><td>输入</td><td>一次下发的AlltoAll通信任务个数。repeat取值≥1，默认值为1。当repeat&gt;1时，每轮AlltoAll任务的sendBuf和recvBuf地址由服务端更新，每一轮任务i的更新公式如下： sendBuf[i] = sendBuf + dataCount * sizeof(datatype) * i, i∈[0, repeat) recvBuf[i] = recvBuf + dataCount * sizeof(datatype) * i, i∈[0, repeat) 注意：当设置repeat&gt;1时，须与strideCount参数配合使用，规划通信数据地址。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>返回该任务的标识handleId，handleId大于等于0。调用失败时，返回 -1。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>调用本接口前确保已调用过<a href="./InitV2.html">InitV2</a>和<a href="./SetCcTilingV2.html">SetCcTilingV2</a>接口。</li><li>若HCCL对象的<a href="./HCCL模板参数.html#table884518212555">config模板参数</a>未指定下发通信任务的核，该接口只能在AIC核或者AIV核两者之一上调用。若HCCL对象的<a href="./HCCL模板参数.html#table884518212555">config模板参数</a>中指定了下发通信任务的核，则该接口可以在AIC核和AIV核上同时调用，接口内部会根据指定的核的类型，只在AIC核、AIV核二者之一下发该通信任务。</li><li>对于Ascend 950PR/Ascend 950DT，通信服务端为CCU时，单次最大通信数据量不能超过256M。</li><li>对于Ascend 950PR/Ascend 950DT，一个通信域内，所有Prepare接口的总调用次数不能超过63。</li><li>对于Atlas A2 训练系列产品/Atlas A2 推理系列产品，一个通信域内，所有Prepare接口的总调用次数不能超过63。</li><li>对于Atlas A3 训练系列产品/Atlas A3 推理系列产品，一个通信域内，所有Prepare接口和InterHcclGroupSync接口的总调用次数不能超过63。</li><li>对于Atlas A3 训练系列产品/Atlas A3 推理系列产品，一个通信域内，最大支持128卡通信。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>非多轮切分场景</p><p>4张卡执行AlltoAll通信任务。非多轮切分场景下，每张卡上的数据块和数据量一致，如下图中每张卡的A\\B\\C\\D数据块，数据量均为dataCount。</p><p><strong>图 1</strong> 非多轮切分场景下4卡AlltoAll通信<br><img src="`+p+`" alt="" title="非多轮切分场景下4卡AlltoAll通信"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extern &quot;C&quot; __global__ __aicore__ void alltoall_custom(GM_ADDR xGM, GM_ADDR yGM, GM_ADDR workspaceGM, GM_ADDR tilingGM) {</span></span>
<span class="line"><span>    constexpr uint64_t dataCount = 128U; // 数据量</span></span>
<span class="line"><span>    auto sendBuf = xGM;  // xGM为AlltoAll的输入GM地址</span></span>
<span class="line"><span>    auto recvBuf = yGM;  // yGM为AlltoAll的输出GM地址</span></span>
<span class="line"><span>    REGISTER_TILING_DEFAULT(AllToAllCustomTilingData); //AllToAllCustomTilingData为对应算子头文件定义的结构体</span></span>
<span class="line"><span>    GET_TILING_DATA_WITH_STRUCT(AllToAllCustomTilingData, tilingData, tilingGM);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Hccl hccl;</span></span>
<span class="line"><span>    GM_ADDR contextGM = AscendC::GetHcclContext&lt;0&gt;();  // AscendC自定义算子kernel中，通过此方式获取HCCL context</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (AscendC::g_coreType == AIV) {  // 指定AIV核通信   </span></span>
<span class="line"><span>        hccl.InitV2(contextGM, &amp;tilingData);</span></span>
<span class="line"><span>        auto ret = hccl.SetCcTilingV2(offsetof(AllToAllCustomTilingData, alltoallCcTiling));</span></span>
<span class="line"><span>	if (ret != HCCL_SUCCESS) {</span></span>
<span class="line"><span>	    return;</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span>	HcclHandle handleId = hccl.AlltoAll&lt;true&gt;(sendBuf, recvBuf, dataCount, HcclDataType::HCCL_DATA_TYPE_FP16);   </span></span>
<span class="line"><span>	hccl.Wait(handleId);   </span></span>
<span class="line"><span>	AscendC::SyncAll&lt;true&gt;();  // AIV核全同步，防止0核执行过快，提前调用hccl.Finalize()接口，导致其他核Wait卡死   </span></span>
<span class="line"><span>	hccl.Finalize();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>多轮切分场景</p><p>使能多轮切分，等效处理上述非多轮切分示例的通信。在每张卡的数据均分成4块（A\\B\\C\\D）的基础上，将每一块继续切分若干块。本例中继续切分3块，如下图所示，被继续切分成的3块数据包括，2个数据量为tileLen的数据块，1个数据量为tailLen的尾块。切分后，需要分3轮进行AlltoAll通信任务，将等效上述非多轮切分的通信结果。</p><p><strong>图 2</strong> 3轮切分场景下4卡AlltoAll通信<br><img src="`+i+'" alt="" title="3轮切分场景下4卡AlltoAll通信"></p><p>具体实现为，第1轮通信，每个rank上0-0\\1-0\\2-0\\3-0数据块进行AlltoAll处理；同一个卡上，参与通信的相邻数据块的间隔为参数strideCount的取值。第2轮通信，每个rank上0-1\\1-1\\2-1\\3-1数据块进行AlltoAll处理。第3轮通信，每个rank上0-2\\1-2\\2-2\\3-2数据块进行AlltoAll处理。第1轮通信的图示及代码示例如下。</p><p><strong>图 3</strong> 第一轮4卡AlltoAll示意图<br><img src="'+c+`" alt="" title="第一轮4卡AlltoAll示意图"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>extern &quot;C&quot; __global__ __aicore__ void alltoall_custom(GM_ADDR xGM, GM_ADDR yGM, GM_ADDR workspaceGM, GM_ADDR tilingGM) {</span></span>
<span class="line"><span>    constexpr uint32_t tileNum = 2U;   // 首块数量</span></span>
<span class="line"><span>    constexpr uint64_t tileLen = 128U; // 首块数据个数</span></span>
<span class="line"><span>    constexpr uint32_t tailNum = 1U;   // 尾块数量</span></span>
<span class="line"><span>    constexpr uint64_t tailLen = 100U; // 尾块数据个数</span></span>
<span class="line"><span>    auto sendBuf = xGM;  // xGM为AlltoAll的输入GM地址</span></span>
<span class="line"><span>    auto recvBuf = yGM;  // yGM为AlltoAll的输出GM地址</span></span>
<span class="line"><span>    REGISTER_TILING_DEFAULT(AllToAllCustomTilingData); //AllToAllCustomTilingData为对应算子头文件定义的结构体</span></span>
<span class="line"><span>    GET_TILING_DATA_WITH_STRUCT(AllToAllCustomTilingData, tilingData, tilingGM);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Hccl hccl;</span></span>
<span class="line"><span>    GM_ADDR contextGM = AscendC::GetHcclContext&lt;0&gt;();  // AscendC自定义算子kernel中，通过此方式获取HCCL context</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (AscendC::g_coreType == AIV) {  // 指定AIV核通信   </span></span>
<span class="line"><span>        hccl.InitV2(contextGM, &amp;tilingData);</span></span>
<span class="line"><span>        auto ret = hccl.SetCcTilingV2(offsetof(AllToAllCustomTilingData, alltoallCcTiling));</span></span>
<span class="line"><span>        if (ret != HCCL_SUCCESS) {</span></span>
<span class="line"><span>          return;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        uint64_t strideCount = tileLen * tileNum + tailLen * tailNum;</span></span>
<span class="line"><span>        // 2个首块处理</span></span>
<span class="line"><span>        HcclHandle handleId1 = hccl.AlltoAll&lt;true&gt;(sendBuf, recvBuf, tileLen, HcclDataType::HCCL_DATA_TYPE_FP16, strideCount, tileNum);</span></span>
<span class="line"><span>        // 1个尾块处理</span></span>
<span class="line"><span>        constexpr uint32_t kSizeOfFloat16 = 2U;</span></span>
<span class="line"><span>        sendBuf += tileLen * tileNum * kSizeOfFloat16;</span></span>
<span class="line"><span>        recvBuf += tileLen * tileNum * kSizeOfFloat16;</span></span>
<span class="line"><span>        HcclHandle handleId2 = hccl.AlltoAll&lt;true&gt;(sendBuf, recvBuf, tailLen, HcclDataType::HCCL_DATA_TYPE_FP16, strideCount, tailNum);</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        for (uint8_t i=0; i&lt;tileNum; i++) {</span></span>
<span class="line"><span>            hccl.Wait(handleId1);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        hccl.Wait(handleId2);  </span></span>
<span class="line"><span>        AscendC::SyncAll&lt;true&gt;();  // 全AIV核同步，防止0核执行过快，提前调用hccl.Finalize()接口，导致其他核Wait卡死   </span></span>
<span class="line"><span>        hccl.Finalize();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul>`,19)])])}const f=l(o,[["render",d]]);export{g as __pageData,f as default};
